dtsPropsFor.Button:
/** Jerarquía visual: primary = acción principal de la vista (una por vista); secondary/outline/ghost = acciones secundarias; soft = acento de marca suave; success = confirmar/completar; danger = eliminar discreto (tablas); destructive = confirmar eliminación. */
variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'soft' | 'success' | 'danger' | 'destructive';
/** sm = compacto (tablas, paginación); md = por defecto; lg = CTA; icon = cuadrado 28px solo ícono (requiere aria-label). */
size?: 'sm' | 'md' | 'lg' | 'icon';
fullWidth?: boolean;
/** Por defecto 'button'; usa 'submit' dentro de formularios. */
type?: 'button' | 'submit' | 'reset';
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
'aria-label'?: string;
title?: string;
/** Texto y/o un ícono *Icon del bundle, p. ej. <PlusIcon /> (se dimensiona a 16px). */
children?: React.ReactNode;
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.CloseButton:
onClick?: React.MouseEventHandler<HTMLButtonElement>;
/** Por defecto 'Cerrar'. */
'aria-label'?: string;
disabled?: boolean;
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.Card:
/** default = panel principal; subtle = elemento dentro de otro panel; interactive = tarjeta/fila clicable (borde de marca al pasar el cursor). */
variant?: 'default' | 'subtle' | 'interactive';
/** none | sm (16px) | md (24px, por defecto) | lg (32px). */
padding?: 'none' | 'sm' | 'md' | 'lg';
/** Sombra grande: modales y formularios centrados. */
elevated?: boolean;
onClick?: React.MouseEventHandler<HTMLDivElement>;
/** Contenido libre; el encabezado se compone con CardHeader > CardTitle + CardDescription. */
children?: React.ReactNode;
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.Input:
type?: 'text' | 'email' | 'password' | 'number' | 'search' | 'url' | 'tel' | 'date' | 'datetime-local' | 'file';
value?: string | number;
defaultValue?: string | number;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
placeholder?: string;
name?: string;
disabled?: boolean;
required?: boolean;
readOnly?: boolean;
min?: number | string;
max?: number | string;
step?: number | string;
autoComplete?: string;
/** Field lo pone automáticamente cuando recibe error. */
'aria-invalid'?: boolean;
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.Textarea:
value?: string;
defaultValue?: string;
onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
placeholder?: string;
rows?: number;
maxLength?: number;
name?: string;
disabled?: boolean;
required?: boolean;
'aria-invalid'?: boolean;
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.Select:
value?: string;
defaultValue?: string;
onChange?: React.ChangeEventHandler<HTMLSelectElement>;
name?: string;
disabled?: boolean;
required?: boolean;
'aria-invalid'?: boolean;
/** Elementos <option> (y opcionalmente <optgroup>). */
children: React.ReactNode;
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.Label:
htmlFor?: string;
children: React.ReactNode;
className?: string;

dtsPropsFor.Field:
label: string;
/** Un único Input, Select o Textarea (Field le asigna id, aria-invalid y aria-describedby), o una función que recibe esos atributos: {(control) => <SearchInput {...control} />}. */
children: React.ReactElement | ((control: { id: string; "aria-invalid": true | undefined; "aria-describedby": string | undefined }) => React.ReactNode);
/** Texto de ayuda bajo el control (no se muestra si hay error). */
hint?: React.ReactNode;
/** Mensaje de error; marca el control como inválido. */
error?: string;
/** id del control (opcional; útil con la forma de función). */
id?: string;
className?: string;

dtsPropsFor.AppRoot:
/** La pantalla completa. */
children?: React.ReactNode;
/** Para una página completa usa "min-h-screen". */
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.Checkbox:
/** Texto junto a la casilla; sin él, pasa aria-label. */
label?: React.ReactNode;
/** Texto secundario bajo la etiqueta. */
description?: React.ReactNode;
checked?: boolean;
defaultChecked?: boolean;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
name?: string;
value?: string;
disabled?: boolean;
required?: boolean;
'aria-label'?: string;
className?: string;
id?: string;

dtsPropsFor.RadioCard:
/** Agrupa varias con el mismo name dentro de un contenedor role="radiogroup". */
name: string;
value?: string;
label: React.ReactNode;
description?: React.ReactNode;
/** Contenido a la derecha, p. ej. <Badge tone="success">Correcta</Badge>. */
trailing?: React.ReactNode;
/** default = selección normal (borde de marca al marcarse); success / danger = revisión de resultados (correcta / incorrecta). */
tone?: 'default' | 'success' | 'danger';
checked?: boolean;
defaultChecked?: boolean;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
disabled?: boolean;
className?: string;
id?: string;

dtsPropsFor.SearchInput:
value?: string;
defaultValue?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
placeholder?: string;
name?: string;
disabled?: boolean;
/** Obligatorio si no hay un Label externo (o úsalo dentro de Field con la forma de función). */
'aria-label'?: string;
/** Se aplica al contenedor: úsalo para el ancho (w-80, w-full). */
className?: string;
id?: string;

dtsPropsFor.Table:
/** TableHead > TableRow > TableHeader y TableBody > TableRow > TableCell (todos exportados). Va dentro de <Card padding="none">. */
children: React.ReactNode;
className?: string;
id?: string;
style?: React.CSSProperties;

dtsPropsFor.SegmentedTabs:
/** Opciones: { value, label, count? } (count se muestra junto a la etiqueta). */
options: { value: string; label: string; count?: number }[];
/** value de la opción seleccionada. */
value: string;
onChange: (value: string) => void;
'aria-label': string;
className?: string;

dtsPropsFor.StateBlock:
/** vacio = todavía no hay datos; error = la carga falló (muestra «Reintentar» por defecto). */
tipo?: 'vacio' | 'error';
/** Componente de ícono del bundle, p. ej. GraduationCapIcon (se pasa el componente, no <GraduationCapIcon />). */
icon?: React.ComponentType<{ className?: string }>;
title?: string;
text?: React.ReactNode;
/** Texto del botón. En error es «Reintentar» por defecto; en vacío solo aparece si se indica. */
action?: string;
onAction?: () => void;
actionVariant?: 'primary' | 'secondary' | 'outline';
/** Menos aire vertical, para usarlo dentro de un panel. */
compact?: boolean;
/** Borde punteado alrededor (por defecto true). */
bordered?: boolean;
/** Elemento del título: p (por defecto) o h1/h2/h3 cuando el bloque es el contenido principal de la página (404, sin permisos). */
titleAs?: 'p' | 'h1' | 'h2' | 'h3';
className?: string;

dtsPropsFor.StatCard:
label: string;
/** Valor principal («90%», «9 / 10»). Sin value, la tarjeta se pinta como placeholder punteado (métricas «Próximamente»). */
value?: React.ReactNode;
/** Texto secundario bajo el valor. */
hint?: React.ReactNode;
/** Componente de ícono del bundle, p. ej. GraduationCapIcon (se pasa el componente, no <GraduationCapIcon />). */
icon?: React.ComponentType<{ className?: string }>;
/** Color del valor. */
tone?: 'default' | 'success' | 'danger';
className?: string;
